const { computeRatio } = require('./bench/sandbox/compute-ratio-ht.js');
const fs = require('fs'), os = require('os'), path = require('path');

function tmp(lines) {
  const f = path.join(os.tmpdir(), 'ht-' + Math.random().toString(36).slice(2) + '.jsonl');
  fs.writeFileSync(f, lines.join('\n'));
  return f;
}

// Example 1
const on1 = tmp([
  JSON.stringify({role:'assistant',usage:{input_tokens:100,output_tokens:50,cache_read_input_tokens:0,cache_creation_input_tokens:0}}),
  JSON.stringify({role:'assistant',usage:{input_tokens:80,output_tokens:30,cache_read_input_tokens:0,cache_creation_input_tokens:0}}),
]);
const off1 = tmp([
  JSON.stringify({role:'assistant',usage:{input_tokens:200,output_tokens:100,cache_read_input_tokens:0,cache_creation_input_tokens:0}}),
]);
console.log('Example 1:', computeRatio(on1, off1));
// expect { gross: 0.8667, net: 0.8667, output: 0.8 }

// Example 2
const on2 = tmp([
  JSON.stringify({role:'assistant',usage:{input_tokens:50,output_tokens:40,cache_read_input_tokens:2000,cache_creation_input_tokens:0}}),
  JSON.stringify({role:'assistant',source:'mcp_tool',usage:{input_tokens:10,output_tokens:5,cache_read_input_tokens:1800,cache_creation_input_tokens:0}}),
]);
const off2 = tmp([
  JSON.stringify({role:'assistant',usage:{input_tokens:200,output_tokens:80,cache_read_input_tokens:200,cache_creation_input_tokens:0}}),
]);
console.log('Example 2:', computeRatio(on2, off2));
// expect { gross: 8.1354, net: 4.3542, output: 0.5625 }
"
